def is_sorted(lst):
    if len(lst) == 0:
        return False

    seen = {}
    for i in range(len(lst)):
        if i > 0 and lst[i] < lst[i - 1]:
            return False
        if lst[i] in seen:
            seen[lst[i]] += 1
        else:
            seen[lst[i]] = 1
        if seen[lst[i]] > 2:
            return False

    return True

